//! Writes a generated site's folder: settings, authors and every post.

use std::fmt::Write as _;
use std::fs;
use std::path::Path;

use crate::fixture::{AUTHORS, CATEGORIES};
use crate::{Fixture, FixtureError};

/// The site's settings: one language, served under `/blog/`.
const SITE_TOML: &str = "\
# Generated by khalid-perf. Do not edit: run scripts/perf.sh again instead.
name = \"Generated Field Notes\"
address = \"https://www.example.com\"
mount = \"/blog/\"
mode = \"server\"
default_language = \"en\"
languages = [\"en\"]
";

/// The posts collection's own page.
const INDEX: &str = "\
---
title: Generated field notes
description: Generated posts on search, written to measure how fast Khalid is.
---

Practical notes for small teams, generated to measure Khalid at scale.
";

impl Fixture {
    /// Writes the site into `dir`, which must be empty or not exist yet.
    ///
    /// # Errors
    ///
    /// [`FixtureError::NotEmpty`] when `dir` holds anything, so a generated
    /// site never mixes with other files, and [`FixtureError::Io`] when a
    /// folder or file cannot be written.
    pub fn write(self, dir: &Path) -> Result<(), FixtureError> {
        if fs::read_dir(dir).is_ok_and(|mut entries| entries.next().is_some()) {
            return Err(FixtureError::NotEmpty {
                path: dir.to_path_buf(),
            });
        }
        save(dir, "site.toml", SITE_TOML)?;
        save(dir, "content/en/posts/_index.md", INDEX)?;
        let mut categories = String::new();
        for slug in CATEGORIES {
            let _ = write!(
                categories,
                "[[categories]]\nslug = \"{slug}\"\nen = \"{slug}\"\n\n"
            );
        }
        save(dir, "categories.toml", &categories)?;
        for (slug, name) in AUTHORS {
            let text = format!(
                "---\nname: {name}\nslug: {slug}\nrole: Writer\n---\n\n\
                 {name} writes practical notes on search for small teams.\n"
            );
            save(dir, format!("content/en/authors/{slug}.md"), &text)?;
        }
        for index in 0..self.posts() {
            save(dir, self.post_path(index), &self.post_text(index))?;
        }
        Ok(())
    }
}

/// Writes `text` to the file `relative` names inside `dir`, making its
/// folder first. Every name is generated here, never read from input.
fn save(dir: &Path, relative: impl AsRef<Path>, text: &str) -> Result<(), FixtureError> {
    let mut path = dir.to_path_buf();
    path.push(relative);
    let io = |source| FixtureError::Io {
        path: path.clone(),
        source,
    };
    if let Some(folder) = path.parent() {
        fs::create_dir_all(folder).map_err(io)?;
    }
    fs::write(&path, text).map_err(io)
}
